:root{
  --bg:var(--appsmith-theme-backgroundColor,#0f172a);
  --surface:var(--appsmith-theme-surfaceColor,#0f172a);
  --card:var(--appsmith-theme-cardColor,#1e293b);
  --alt:var(--appsmith-theme-surfaceAltColor,#1e293b);
  --hover:var(--appsmith-theme-surfaceHoverColor,#26344b);
  --line:var(--appsmith-theme-borderColor,#334155);
  --line2:var(--appsmith-theme-borderMidColor,#475569);
  --strong:var(--appsmith-theme-textStrongColor,#ffffff);
  --text:var(--appsmith-theme-textColor,#e2e8f0);
  --soft:var(--appsmith-theme-textSecondaryColor,#94a3b8);
  --muted:var(--appsmith-theme-textMutedColor,#64748b);
  --link:var(--appsmith-theme-linkColor,#60a5fa);
  --action:var(--appsmith-theme-actionColor,#2563eb);
  --danger:var(--appsmith-theme-dangerColor,#f87171);
  --ok:var(--appsmith-theme-successColor,#34d399);
}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:var(--surface);color:var(--text);font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;font-size:14px}
#root{height:100%;overflow:auto}
.page{padding:20px 24px 40px;display:flex;flex-direction:column;gap:16px;max-width:1500px}
h1{margin:0 0 4px;font-size:24px;color:var(--strong)}
h2{margin:0;font-size:17px;color:var(--strong)}
.title-row,.card-head,.alias-head,.group-head,.bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.grow{flex:1}
.muted{color:var(--soft)}
.small{font-size:12.5px}
.pad{padding:18px 4px}
.hint{margin:2px 0 8px}
.err{color:var(--danger)}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12.5px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px 18px;display:flex;flex-direction:column;gap:10px}
.card-head{margin-bottom:4px}
.inp{height:34px;border:1px solid var(--line2);border-radius:6px;background:var(--surface);color:var(--text);padding:0 10px;font:inherit;min-width:0}
.inp:focus{outline:2px solid var(--action);outline-offset:-1px}
.inp:disabled{opacity:.5}
.inp.sm{width:auto}
.inp.date{width:150px}
.inp.preset{width:300px}
select.inp{cursor:pointer}
.row{display:grid;grid-template-columns:64px minmax(180px,1.2fr) minmax(150px,.9fr) minmax(200px,1.6fr) 30px;gap:10px;align-items:center}
.row-wrap{display:grid;grid-template-columns:64px 1fr;gap:10px;align-items:start}
.lead{display:inline-flex;justify-content:center;align-items:center;height:30px;border-radius:6px;background:var(--alt);border:1px solid var(--line);color:var(--soft);font-weight:700;font-size:12.5px}
.val{display:flex;gap:8px;align-items:center;min-width:0}
.val .inp{flex:1}
.val.two .inp{flex:1}
.mode{height:34px;padding:0 9px;border-radius:6px;border:1px dashed var(--line2);background:transparent;color:var(--soft);font:inherit;font-size:12px;cursor:pointer;white-space:nowrap}
.mode:hover{color:var(--strong);border-color:var(--soft)}
.x{width:30px;height:30px;border:0;border-radius:6px;background:transparent;color:var(--muted);font-size:20px;line-height:1;cursor:pointer}
.x:hover{background:var(--hover);color:var(--danger)}
.group{border:1px dashed var(--line2);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;gap:10px}
.adds{display:flex;gap:10px;flex-wrap:wrap}
.btn{height:34px;padding:0 14px;border-radius:6px;font:inherit;font-weight:600;cursor:pointer;border:1px solid var(--line2);background:transparent;color:var(--text)}
.btn.ghost:hover{background:var(--hover)}
.btn.primary{background:var(--action);border-color:var(--action);color:#fff}
.btn.primary:disabled{opacity:.55;cursor:default}
.alias{border:1px solid var(--line);border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:10px;background:var(--surface)}
.badge{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:6px;background:var(--action);color:#fff;font-weight:800}
.pill{padding:3px 10px;border-radius:999px;background:var(--alt);border:1px solid var(--line);color:var(--soft);font-size:12.5px}
.bar{position:sticky;bottom:0;z-index:2;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 14px}
.dot{width:9px;height:9px;border-radius:50%;background:var(--ok)}
.dot.bad{background:var(--danger)}
.sql{margin:0;padding:14px;border-radius:8px;background:var(--surface);border:1px solid var(--line);color:var(--soft);white-space:pre-wrap;word-break:break-word;font-family:ui-monospace,Menlo,monospace;font-size:12px;max-height:320px;overflow:auto}
.mp{position:relative;flex:1;min-width:0}
.mp-btn{width:100%;text-align:left;display:flex;align-items:center;cursor:pointer;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.mp-btn.ph{color:var(--muted)}
.chev{margin-left:auto;padding-left:8px;color:var(--muted)}
.mp-pop{position:absolute;z-index:10;top:38px;left:0;right:0;min-width:280px;background:var(--card);border:1px solid var(--line2);border-radius:8px;box-shadow:0 10px 30px rgba(0,0,0,.35);padding:8px;display:flex;flex-direction:column;gap:6px}
.mp-pop .inp{width:100%}
.mp-acts{display:flex;justify-content:space-between;font-size:12.5px}
.mp-acts a{color:var(--link);cursor:pointer}
.mp-list{max-height:260px;overflow:auto}
.mp-row{display:flex;align-items:center;gap:8px;padding:5px 4px;border-radius:4px;cursor:pointer}
.mp-row:hover{background:var(--hover)}
.cnt{margin-left:auto;color:var(--muted);font-size:12px}
.tbl-wrap{overflow:auto;max-height:560px;border:1px solid var(--line);border-radius:8px}
.tbl{width:100%;border-collapse:collapse}
.tbl th{position:sticky;top:0;background:var(--alt);text-align:left;padding:10px 14px;color:var(--soft);font-size:12.5px;font-weight:700;white-space:nowrap;border-bottom:1px solid var(--line)}
.tbl td{padding:9px 14px;border-bottom:1px solid var(--line);white-space:nowrap;max-width:280px;overflow:hidden;text-overflow:ellipsis}
.tbl tr:hover td{background:var(--hover)}
.num{text-align:right}
.link{color:var(--link);cursor:pointer;font-weight:600}
.link:hover{text-decoration:underline}
.val-empty{min-height:34px}
@media (max-width:900px){.row{grid-template-columns:56px 1fr 1fr;}.row .val,.row .val-empty{grid-column:2/4}.row .x{grid-column:3;justify-self:end}}

